<script module lang="ts">
/**
 * An agent run's steps, each with its status (`design/components/plan.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/plan.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import { Icon, joinSlot } from '@polymorph/svelte'
import styles from '@polymorph/recipes/ai/plan.module.css'

export type PlanStatus = 'pending' | 'running' | 'done' | 'error' | 'skipped'

export interface PlanStep {
  id: string
  title: string
  description?: string
  status: PlanStatus
}

export interface PlanMessages {
  status: Record<PlanStatus, string>
}

export interface PlanProps {
  /**
   * The list's accessible name, such as "Plan for this run" rather than "Plan".
   */
  label: string
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: PlanMessages
  /**
   * The steps in reading order. Plan never sorts them, and an empty list renders nothing.
   */
  steps: PlanStep[]
}
</script>

<script lang="ts">
let {
  label: labelOwn,
  messages = (() => ({
    status: {
      pending: 'Pending',
      running: 'Running',
      done: 'Done',
      error: 'Failed',
      skipped: 'Skipped',
    },
  }))(),
  steps,
}: PlanProps = $props()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
const currentId = $derived(steps.find((step) => step.status === 'running')?.id)
const announcement = $derived(
  ((front: PlanStep | undefined) =>
    front === undefined ? '' : `${front.title}, ${messages.status[front.status]}`)(
    steps.find((step) => step.status === 'running') ??
      steps.find((step) => step.status === 'error') ??
      [...steps].reverse().find((step) => step.status === 'done' || step.status === 'skipped'),
  ),
)
</script>

{@render joined.start?.()
}{#if joined.shown
  }{#if steps.length > 0
    }<div class={styles.root} data-member="plan"
      ><ol class={styles.list} role="list" aria-label={label}
        >{#each steps as step (step.id)
          }<li
            class={styles.step}
            data-status={step.status}
            aria-current={(step.id === currentId) ? 'step' : undefined}
            aria-busy={(step.status === 'running') ? true : undefined}
            ><span class={styles.mark} aria-hidden="true"
              >{#if step.status === 'running'
                }<span class={[styles.glyph, styles.spinning]}
                  ><Icon name="loading" size="sm"
                /></span
              >{:else if step.status === 'done'
                }<span class={styles.glyph}><Icon name="success" size="sm" /></span
              >{:else if step.status === 'error'
                }<span class={styles.glyph}><Icon name="error" size="sm" /></span
              >{:else if step.status === 'skipped'
                }<span class={styles.glyph}><Icon name="remove" size="sm" /></span
              >{:else
                }<span class={styles.glyph}><Icon name="time" size="sm" /></span
              >{/if
            }</span
            ><span class={styles.copy}
              ><span class={styles.title}>{step.title}</span
              ><span class={styles.reader}>{`, ${messages.status[step.status]}`}</span
              >{#if step.description !== undefined
                }<span class={styles.description}>{step.description}</span
              >{/if
            }</span
          ></li
        >{/each
      }</ol
      ><p class={styles.line} role="status">{announcement}</p
    ></div
  >{/if
}{/if
}{@render joined.end?.()}
